String generatePassword(){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#\$%^&*';final r=Random.secure();return List.generate(24,(_)=>chars[r.nextInt(chars.length)]).join();}
class PasswordScreen extends StatefulWidget{final String serviceName;final int days;final List<Map<String,String>> selectedApps;const PasswordScreen({super.key,required this.serviceName,required this.selectedApps,required this.days});@override State<PasswordScreen> createState()=>_PasswordScreenState();}
class _PasswordScreenState extends State<PasswordScreen>{late final String password;bool enabled=false,copied=false,visible=false;@override void initState(){super.initState();password=generatePassword();}Future<void> copy()async{await Clipboard.setData(ClipboardData(text:password));if(mounted)setState(()=>copied=true);}void next()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>ConfirmLockScreen(serviceName:widget.serviceName,selectedApps:widget.selectedApps,password:enabled?password:null,days:widget.days)));
 @override Widget build(BuildContext context)=>RebootScaffold(child:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,12,20,0),child:Row(children:[const RebootBackButton(),const SizedBox(width:14),const Text('Commitment options',style:TextStyle(fontSize:16,fontWeight:FontWeight.w800))])),Expanded(child:ListView(padding:const EdgeInsets.fromLTRB(22,30,22,25),children:[const RebootEyebrow('Step 3 of 3'),const SizedBox(height:13),const Text('Add an extra layer of commitment.',style:TextStyle(fontSize:30,fontWeight:FontWeight.w800)),const SizedBox(height:12),const Text('Password protection is optional. Reboot can block selected apps and track your commitment without changing account passwords.',style:TextStyle(color:RebootColors.muted,fontSize:14,height:1.55)),const SizedBox(height:20),RebootCard(child:SwitchListTile(contentPadding:EdgeInsets.zero,value:enabled,onChanged:(v)=>setState(()=>enabled=v),activeColor:RebootColors.mint,title:const Text('Use password protection',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:const Text('Reveal a generated password when your commitment ends.',style:TextStyle(color:RebootColors.muted,fontSize:12)))),if(enabled)...[const SizedBox(height:14),RebootCard(child:Column(children:[SelectableText(visible?password:'•'*password.length,style:const TextStyle(fontWeight:FontWeight.w800,letterSpacing:1)),Row(children:[TextButton.icon(onPressed:()=>setState(()=>visible=!visible),icon:Icon(visible?Icons.visibility_off:Icons.visibility),label:Text(visible?'Hide':'Show')),const Spacer(),OutlinedButton.icon(onPressed:copy,icon:const Icon(Icons.copy),label:Text(copied?'Copied':'Copy'))])])),const SizedBox(height:8),const Text('The password is encrypted with Android Keystore-backed encryption and is not stored in the normal commitment record.',style:TextStyle(color:RebootColors.muted,fontSize:11))],const SizedBox(height:24),RebootPrimaryButton(label:'Continue to review',icon:Icons.arrow_forward_rounded,onPressed:enabled&&!copied?null:next),const SizedBox(height:8),Text(enabled?'Copy the password before continuing.':'Continue without password protection.',textAlign:TextAlign.center,style:const TextStyle(color:RebootColors.muted,fontSize:11))]))]));}
